/* Lcd Bank Functions --------------------------------------------------------*/

void Controller::lcd_drawEncoderBankTab() {
    /// @brief Displays active global encoder bank number indicator.

    // 1. STYLE SETUP
    // Configure footer text style.
    lcd.setAlignment(CENTER);
    lcd.setFont(FONT_07x09);

    // 2. LABEL DRAW
    // Draw static KNOB footer label.
    lcd.setForeColor(MAGENTA);
    lcd.drawText("KNOB", 4, 76, 463);

    // 3. BANK VALUE DRAW
    // Draw two-digit active encoder bank index.
    lcd.setForeColor(WHITE);
    char textData[3];
    sprintf(textData, "%02d", activeEncoderBank + 1);
    lcd.drawText(textData, 2, 76, 489);
}

void Controller::lcd_drawSongBankTab(uint8_t bank_, bool mode_) {
    /// @brief Displays song bank number with optional highlight color.

    // 1. STYLE SETUP
    // Configure footer text style.
    lcd.setAlignment(CENTER);
    lcd.setFont(FONT_07x09);

    // 2. LABEL DRAW
    // Draw static SONG footer label.
    lcd.setForeColor(MAGENTA);
    lcd.drawText("SEQUENCE", 8, 886, 463);   // custom: was SONG (a song is the whole arrangement)

    // 3. HIGHLIGHT STATE APPLY
    // Select highlighted color when requested.
    (mode_) ? lcd.setForeColor(MAGENTA) : lcd.setForeColor(WHITE);

    // 4. BANK VALUE DRAW
    // Draw two-digit selected bank index.
    char textData[3];
    sprintf(textData, "%02d", bank_ + 1);
    lcd.drawText(textData, 2, 886, 489);
}

void Controller::lcd_drawSongBankShift() {
    /// @brief Handles deferred song-bank shift redraw when bank action is pending.

    // 1. BANK SHIFT GATE
    // Apply redraw flow only when bank action flag is armed.
    if (bankActionFlag) {
        bankActionFlag = false;

        // 2. BANK TAB REFRESH
        // Refresh bank tab indicator.
        lcd_drawSongBankTab(activeSongBank, false);

        // 3. SONG GRID REFRESH
        // Redraw all layer/bank song lanes.
        for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
            for (uint8_t j = 0; j < kBankLibrarySize; j++) {
                lcd_drawSong(i, j);
            }
        }
    }
}

/* Lcd Menu Functions --------------------------------------------------------*/

void Controller::lcd_drawMenuIcon(Menu menu_) {
    /// @brief Draws left/right menu icon indicators based on active menu type.

    // 1. COMMON STYLE SETUP
    // Configure common icon text style and spacing.
    lcd.setForeColor(WHITE);
    lcd.setBackColor(BLACK);
    lcd.setFont(FONT_10x14);
    lcd.setAlignment(CENTER);
    lcd.setSpacing(4);

    // 2. LEFT ICON DRAW
    // Custom: a short word for the menu (FILE, FX1, LFO3, INST7 ...) instead of one letter.
    lcd_drawMenuLabel(menu_, -1);

    // 3. RIGHT ICON DRAW
    // Custom: the stock four-square icon is replaced by the current project name.
    lcd.setSpacing(2);
    lcd_drawProjectName();
}

void Controller::lcd_drawMenuLabel(Menu menu_, int16_t num_) {
    /// @brief Custom: draws the menu name in the top-left box. num_ < 0 = work it out from the
    /// current selection (filter/effect 1-2, LFO 1-10, drum 1-10).
    const char* word = "";
    int16_t num = -1;
    switch (menu_) {
        case GLOBAL_MENU:       word = (page == PAGE_SONG) ? "SONG" : "MAIN"; break;   // custom
        case FILE_MENU:         word = "FILE"; break;
        case DRUMKIT_MENU:      word = "KIT"; break;
        case MIXER_MENU:        word = "ROUTE"; break;   // custom: Mixer key, first press
        case RHYTHM_MENU:       word = "RHYTHM"; break;
        case METRO_MENU:        word = "MIX"; break;     // custom: mix volumes + metronome
        case IO_MENU:           word = (page == PAGE_PITCH) ? (levelsMode ? "LEVELS" : "NOTES") : "SYNC"; break;
        case EQ_MENU:           word = "EQ"; break;
        case REVERB_MENU:       word = "REVERB"; break;
        case FILTER_0_MENU:     word = "FILT"; num = 1; break;
        case FILTER_1_MENU:     word = "FILT"; num = 2; break;
        case EFFECT_0_MENU:     word = "FX"; num = 1; break;
        case EFFECT_1_MENU:     word = "FX"; num = 2; break;
        case LFO_MENU:          word = "LFO"; num = selectedLfoNum + 1; break;
        case LAYER_INST_0_MENU:
        case LAYER_INST_1_MENU:
        case LAYER_INST_2_MENU: word = "INST"; num = selectedLayerNum + 1; break;
        case LAYER_SONG_MENU:   word = "HITS"; num = selectedLayerNum + 1; break;   // custom: was SEQ (sequences are 1-5)
        default:                word = ""; break;
    }
    if (num_ >= 0) num = num_;
    char text[12];
    if ((num >= 1) && (num <= 99)) snprintf(text, sizeof(text), "%s%d", word, num);
    else snprintf(text, sizeof(text), "%s", word);

    const LcdFont font = lcd.getFont();
    const LcdAlign align = lcd.getAlignment();
    const uint16_t spacing = lcd.getSpacing();
    lcd.setBackColor(BLACK);
    lcd.clearRect(kMenuNumX, kMenuNumY, 7, 9);                            // old small number spot
    lcd.clearRect(kMenuIconLeftX - 48, kMenuIconLeftY - 4, 96, 22);
    lcd.setFont(FONT_10x14);
    lcd.setSpacing(1);
    lcd.setAlignment(CENTER);
    lcd.setForeColor(WHITE);
    if (text[0] != 0) lcd.drawText(text, strlen(text), kMenuIconLeftX, kMenuIconLeftY);
    lcd.setFont(font);
    lcd.setAlignment(align);
    lcd.setSpacing(spacing);
}

void Controller::lcd_drawProjectName() {
    /// @brief Custom: shows which project is open (FILE_006 etc.) in the top-right corner.
    const LcdFont font = lcd.getFont();
    const LcdAlign align = lcd.getAlignment();
    const uint16_t spacing = lcd.getSpacing();
    char text[12];
    // The LCD font has no '*', so unsaved changes show as a small orange square after the name.
    if (currentFileNum >= 0) snprintf(text, sizeof(text), "FILE_%03d", currentFileNum + 1);
    else snprintf(text, sizeof(text), "NEW");
    lcd.setBackColor(BLACK);
    lcd.clearRect(kMenuIconRightX - 46, kMenuIconRightY - 4, 96, 22);
    lcd.setFont(FONT_10x14);
    lcd.setSpacing(0);
    lcd.setAlignment(CENTER);
    lcd.setForeColor(kThemeDark ? kThemeAccent : WHITE);
    lcd.drawText(text, strlen(text), kMenuIconRightX - 2, kMenuIconRightY);
    if (projectDirty) {
        const uint16_t right = (kMenuIconRightX - 2) + (strlen(text) * 10) / 2;
        lcd.fillRect(right + 3, kMenuIconRightY + 9, 5, 5);
    }
    lcd.setFont(font);
    lcd.setAlignment(align);
    lcd.setSpacing(spacing);
}

void Controller::lcd_drawEncoderBox(uint8_t encoderNum_) {
    /// @brief Draws encoder activity box color based on encoder mode and function.

    // 1. MODE DISPATCH
    // Select color and draw path based on global/local encoder mode.
    RGB16Color color;
    Encoder& enc = encoder[encoderNum_];

    switch (enc.mode) {
        case ENC_MODE_GLOBAL:
            switch (encoder[encoderNum_].function) {
                case ENC_FNC_NONE:
                    color = BLACK;
                    break;

                case ENC_FNC_OFF:
                    color = kEncoderGlobalInactiveColor;
                    break;

                default:
                    color = kEncoderGlobalActiveColor;
                    break;
            }
            lcd.setForeColor(color);
            lcd.fillRect(kMenuEncoderBoxX[encoderNum_], kMenuEncoderBoxY[encoderNum_], kMenuEncoderBoxWidth, kMenuEncoderBoxHeight);
            break;

        case ENC_MODE_LOCAL: {
            switch (encoder[encoderNum_].function) {
                case ENC_FNC_NONE:
                    color = BLACK;
                    break;

                case ENC_FNC_OFF:
                    color = kEncoderLocalInactiveColor;
                    break;

                default:
                    color = kEncoderLocalActiveColor;
                    break;
            }
            lcd.setForeColor(color);
            if ((menu != LFO_MENU) && (menu != LAYER_INST_0_MENU) && (menu != LAYER_INST_1_MENU) && (menu != LAYER_INST_2_MENU) && (menu != LAYER_SONG_MENU)) {
                // Draw activity indicator
                lcd.fillRect(kMenuEncoderBoxX[encoderNum_], kMenuEncoderBoxY[encoderNum_], kMenuEncoderBoxWidth, kMenuEncoderBoxHeight);
            } else if ((encoderNum_ != 2) && (encoderNum_ != 3)) {
                bool active = (encoder[encoderNum_].function != ENC_FNC_NONE) ? true : false;

                // Draw activity indicator
                lcd.fillRect(kMenuEncoderBoxX[encoderNum_], kMenuEncoderBoxY[encoderNum_], kMenuEncoderBoxWidth, kMenuEncoderBoxHeight);
            }
        } break;
    }
}

void Controller::lcd_drawFileBox(uint8_t menuTab_, FileStatus status_) {
    /// @brief Draws file status indicator box using state-based color coding.

    // 1. POSITION CALCULATION
    // Resolve file-box position for selected menu tab.
    uint16_t xPos = kMenuFileBoxX[menuTab_];
    uint16_t yPos = kMenuFileBoxY[menuTab_];

    // 2. STATUS COLOR DRAW
    // Draw file box with color corresponding to file status.
    switch (status_) {
        case FILE_NONE:
            lcd.setForeColor(MAGENTA);
            lcd.setBackColor(BLACK);
            lcd.clearRect(xPos, yPos, kMenuFileBoxWidth, kMenuFileBoxHeight);
            lcd.fillRect(xPos, yPos, kMenuFileBoxWidth, kMenuFileBoxHeight);
            break;

        case FILE_MISSING:
            lcd.setForeColor(MAGENTA);
            lcd.setBackColor(BLACK);
            lcd.clearRect(xPos, yPos, kMenuFileBoxWidth, kMenuFileBoxHeight);
            lcd.fillRect(xPos, yPos, kMenuFileBoxWidth, kMenuFileBoxHeight);
            break;

        case FILE_INCOMPATIBLE:
            lcd.setForeColor(MAGENTA);
            lcd.setBackColor(BLACK);
            lcd.clearRect(xPos, yPos, kMenuFileBoxWidth, kMenuFileBoxHeight);
            lcd.fillRect(xPos, yPos, kMenuFileBoxWidth, kMenuFileBoxHeight);
            break;

        case FILE_INACTIVE:
            lcd.setForeColor(GRAY_75);
            lcd.setBackColor(BLACK);
            lcd.clearRect(xPos, yPos, kMenuFileBoxWidth, kMenuFileBoxHeight);
            lcd.fillRect(xPos, yPos, kMenuFileBoxWidth, kMenuFileBoxHeight);
            break;

        case FILE_ACTIVE:
            lcd.setForeColor(GREEN);
            lcd.setBackColor(BLACK);
            lcd.fillRect(xPos, yPos, kMenuFileBoxWidth, kMenuFileBoxHeight);
            break;
    }
}

