    lcd_setMenuDataState(WHITE);

    // 2. VALUE DRAW
    // Draw current bar value.
    lcd.drawText(kNumberDataLibrary[rhythm.bar].nameLongR, kMenuDataTextSize, kMenuDataX[2], kMenuDataY[2]);

