            textPtr = kNumberDataLibrary[effect_.phaser.eDry].nameLongR;
            break;

        case EF_COMPRESSOR:
            textPtr = kNumberDataLibrary[effect_.compressor.eDry].nameLongR;
            break;

        case EF_EXPANDER:
            textPtr = kNumberDataLibrary[effect_.expander.eDry].nameLongR;
            break;

        case EF_OVERDRIVE:
